SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=30)/COUNT(*),2), ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=90)/COUNT(*),2), ROUND(100*SUM(closing_balance) FILTER (WHERE days_past_due>=30)/SUM(closing_balance),2), ROUND(100*SUM(closing_balance) FILTER (WHERE days_past_due>=90)/SUM(closing_balance),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2021-12-31' AND loan_status<>'Closed'
